using System;
using System.Globalization;

class Solution
{
    static void Main(string[] args)
    {
        string[] DK = Console.ReadLine().Split(' ');
        int D = int.Parse(DK[0]);
        int K = int.Parse(DK[1]);
        string[] RaRb = Console.ReadLine().Split(' ');
        int Ra = int.Parse(RaRb[0]);
        int Rb = int.Parse(RaRb[1]);
        float S = float.Parse(Console.ReadLine(), CultureInfo.InvariantCulture);

        double E = 1 / (1 + Math.Pow(10d, (Rb - Ra) / D));
        double RaNew = Ra + K * (S - E);

        Console.WriteLine(Math.Round(RaNew));
    }
}
